import { hashInitCode } from "./create2";

// Example contract bytecodes (compiled from Solidity / Foundry)
export const exampleContracts = {
  simpleStorage: {
    name: "SimpleStorage",
    bytecode:
      "",
    description: "SimpleStorage with store() and retrieve()",
  },
} as const;

/** keccak256(init_code) for `exampleContracts.simpleStorage.bytecode` — use as default init code hash in the UI. */
export const SIMPLE_STORAGE_INIT_CODE_HASH = hashInitCode(
  exampleContracts.simpleStorage.bytecode,
) as `0x${string}`;